#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>
#include <vector>
#include <format>

std::string etiqueta(const std::string& codigo, int cantidad) {
    return std::format("[{0:<6}]|[{1:04d}]|[{1:x}]", codigo, cantidad);
}

int main() {
    int cantidad = 10;
    std::cout << etiqueta("Sol", cantidad) << "\n" << etiqueta("Couloir", 31) << "\n"
        << etiqueta("", 0) << "\n" << etiqueta("Bureau", 1000) << "\n" << cantidad + 1;
    return 0;
}

